head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    debugger;
    var tmpObj = tabc_side.getWindow(1);
    dataList2.setBroadcast(false);
    //선택 된 tab의 컨텐츠에 있는 input1 컴포넌트에 value를 설정.
    dataList2.insertRow(0);
    dataList2.setBroadcast(true, true);
};
scwin.checkVal = function() {
	console.log(WebSquare.wUnit.getDomById('gridView1_headerRowNumber_bodyRow_5').innerText)
    return WebSquare.wUnit.getDomById('gridView1_headerRowNumber_bodyRow_5').innerText == '10';
}
